// Clean The Email - one item per email. Deterministic noise filter: the model never sees
// auto-replies, bulk mail, mailing lists or senders/subjects on the ignore lists.
const rules = $('Feedback Rules').first().json;
const list = (s) => String(s || '').toLowerCase().split(',').map((x) => x.trim()).filter(Boolean);
const ignoreSenders = list(rules.ignore_senders);
const ignoreSubjects = list(rules.ignore_subjects);
const max = Number(rules.max_email_chars) || 4000;

return $input.all().map((item) => {
  const m = item.json;
  const h = m.headers || {};
  // The Gmail trigger (simple off) gives each header as the whole line, "Auto-Submitted: no",
  // not the bare value (measured on exec 2304). Strip the "Name: " part before comparing.
  const header = (k) => {
    const v = h[k];
    if (v === undefined || v === null) return '';
    const s = (typeof v === 'string' ? v : JSON.stringify(v)).toLowerCase();
    return s.indexOf(k + ':') === 0 ? s.slice(k.length + 1).trim() : s.trim();
  };
  const first = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddress = String(first.address || '').toLowerCase();
  const fromName = String(first.name || '');
  const subject = String(m.subject || '');
  const raw = String(m.text || '').split('\r\n').join('\n');
  const kept = [];
  for (const line of raw.split('\n')) {
    const t = line.trim();
    if (/^On .+wrote:$/.test(t)) break;
    if (t === '--') break;
    if (t.indexOf('>') === 0) continue;
    kept.push(line);
  }
  const body = kept.join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);

  // Every message this workflow sends can land back in the inbox it reads: replies keep the
  // customer's subject (no "Re:", exec 2305) and team notices may go to the same inbox (exec 2322).
  // Only this inbox's own mail carries the SENT label; a customer's never does. A sent message that
  // holds our signature (or, as a fallback, our thank-you or reply footer) is ours and is dropped.
  const sentByUs = (m.labelIds || []).indexOf('SENT') >= 0;
  const has = (t) => String(t || '').trim() !== '' && body.indexOf(String(t).trim()) >= 0;
  const ownText = has(rules.mail_signature) || has(rules.reply_footer) ||
    body === String(rules.thank_you_message || '').trim();

  let reason = '';
  const auto = header('auto-submitted');
  if (sentByUs && ownText) reason = 'our own reply';
  else if (auto && auto !== 'no') reason = 'auto-submitted header (' + auto + ')';
  else if (['bulk', 'list', 'junk'].indexOf(header('precedence')) >= 0) reason = 'bulk mail';
  else if (header('list-unsubscribe')) reason = 'mailing list (List-Unsubscribe header)';
  else if (ignoreSenders.some((s) => fromAddress.indexOf(s) >= 0)) reason = 'sender on the ignore list';
  else if (ignoreSubjects.some((s) => subject.toLowerCase().indexOf(s) >= 0)) reason = 'subject on the ignore list';
  else if (body.length < 3) reason = 'empty message';

  return {
    json: {
      message_id: m.id,
      thread_id: m.threadId,
      from_address: fromAddress,
      from_name: fromName,
      subject: subject,
      body: body,
      is_noise: reason !== '',
      noise_reason: reason,
    },
  };
});

// List Open Issues For Triage - runs once per email. Reads Linear's answer, finds the team, and
// checks whether THIS email was already filed (a [msg:<id>] marker in a description or comment),
// so a re-delivered email never becomes a second issue or a second comment.
const email = $('Clean The Email').item.json;
const rules = $('Feedback Rules').first().json;
const data = ($json && $json.data) || {};
const teams = (data.teams && data.teams.nodes) || [];
const issues = (data.issues && data.issues.nodes) || [];
const marker = 'msg:' + email.message_id;

let filedIn = '';
for (const i of issues) {
  const texts = [String(i.description || '')].concat(((i.comments && i.comments.nodes) || []).map((c) => String(c.body || '')));
  if (texts.some((t) => t.indexOf(marker) >= 0)) { filedIn = i.identifier; break; }
}
const lines = issues.map((i) => {
  const about = String(i.description || '').split('\n---\n')[0].replace(/\s+/g, ' ').trim().slice(0, 200);
  return i.identifier + ' | ' + i.title + (about ? ' | ' + about : '');
});

let holdReason = '';
if (!data.teams) holdReason = 'Linear did not answer: ' + JSON.stringify($json.errors || $json.error || $json).slice(0, 300);
else if (!teams.length) holdReason = 'No Linear team has the key "' + rules.linear_team_key + '". Set linear_team_key in Feedback Rules.';

return {
  json: Object.assign({}, email, {
    team_id: teams.length ? teams[0].id : '',
    hold_reason: holdReason,
    already_filed_in: filedIn,
    open_issue_count: issues.length,
    open_issues_text: lines.join('\n'),
    marker: marker,
  }),
};

