parameters.jsCode:
// Check The Triage Answer - runs once per email. The model proposes; this node decides what is
// allowed. A weak or malformed match is filed as NEW (never silently merged), a missing question
// or a missing decision HOLDS the email, and the customer quote must really appear in the email.
const ctx = $('List Open Issues For Triage').item.json;
const rules = $('Feedback Rules').first().json;
const out = ($json && $json.output) || {};
const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const minConf = Number(rules.min_match_confidence);

let decision = String(out.decision || '').toLowerCase().trim();
let reason = String(out.reason || '').trim();
let matched = String(out.matched_issue || '').toUpperCase().trim();
let conf = Number(out.confidence);
if (conf > 1) conf = conf / 100;
let possibleDuplicate = '';
let holdReason = '';

if ($json && $json.error) {
  // the agent's error output is wired here too: a model that did not answer holds the email
  const e = $json.error;
  holdReason = 'The AI model did not answer: ' + String((e && e.message) || e).slice(0, 300);
} else if (['new', 'same', 'unclear'].indexOf(decision) < 0) {
  holdReason = 'The model gave no usable decision (' + (decision || 'empty') + ').';
}
if (decision === 'same' && !/^[A-Z][A-Z0-9]*-[0-9]+$/.test(matched)) {
  decision = 'new';
  reason = 'No valid issue id came with the match, so it was filed as new. ' + reason;
}
if (decision === 'same' && !(conf >= minConf)) {
  possibleDuplicate = matched;
  decision = 'new';
  reason = 'Match confidence ' + conf + ' is below ' + minConf + ', so it was filed as new. ' + reason;
}
if (decision !== 'same') matched = '';

const question = String(out.question_for_customer || '').trim();
if (decision === 'unclear' && question.length < 10) holdReason = 'The model asked for more detail but wrote no question.';

let quote = String(out.customer_quote || '').trim();
if (!quote || norm(ctx.body).indexOf(norm(quote)) < 0) quote = ctx.body.slice(0, 300);
const quoteMd = quote.split('\n').map((l) => '> ' + l).join('\n');
const title = String(out.title || '').replace(/\s+/g, ' ').trim().slice(0, 120) || ctx.subject || 'Customer feedback';
const summary = String(out.summary || '').trim() || 'A customer wrote in about this. Their words are quoted below.';

return {
  json: {
    decision: holdReason ? 'hold' : decision,
    hold_reason: holdReason,
    matched_issue: matched,
    possible_duplicate_of: possibleDuplicate,
    confidence: isNaN(conf) ? null : conf,
    title: title,
    summary: summary,
    customer_quote: quote,
    quote_md: quoteMd,
    question_for_customer: decision === 'unclear' ? question : '',
    reason: reason,
    message_id: ctx.message_id,
    from_address: ctx.from_address,
    from_name: ctx.from_name,
    subject: ctx.subject,
    team_id: ctx.team_id,
    marker: ctx.marker,
  },
};

