// Rank The Most Requested - counts customer requests per open issue. A request is the
// [msg:<id>] marker this workflow writes: one in the description of an issue it created, one in
// each comment it added. Issues nobody asked for through this workflow are left out.
const rules = $('Feedback Rules').first().json;
const top = Number(rules.digest_top) || 10;
const weekAgo = Date.now() - 7 * 86400000;
const issues = ((($json && $json.data) || {}).issues || {}).nodes || [];

const ranked = [];
for (const i of issues) {
  const comments = ((i.comments && i.comments.nodes) || []).filter((c) => String(c.body || '').indexOf('[msg:') >= 0);
  const fromDescription = String(i.description || '').indexOf('[msg:') >= 0 ? 1 : 0;
  const total = fromDescription + comments.length;
  if (!total) continue;
  let thisWeek = comments.filter((c) => Date.parse(c.createdAt) >= weekAgo).length;
  if (fromDescription && Date.parse(i.createdAt) >= weekAgo) thisWeek += 1;
  ranked.push({ id: i.identifier, title: i.title, url: i.url, total: total, this_week: thisWeek });
}
ranked.sort((a, b) => b.total - a.total || b.this_week - a.this_week);
const shown = ranked.slice(0, top);
const text = shown.length
  ? ['Most requested open issues (requests in total, new this week):', '']
      .concat(shown.map((r, n) => (n + 1) + '. ' + r.id + ' ' + r.title + ' - ' + r.total + ' total, ' + r.this_week + ' this week - ' + r.url))
      .join('\n')
  : '';

return [{ json: { ranked_count: shown.length, open_issues_read: issues.length, text: text, ranked: shown } }];
